do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Serving Neighbors, Interpreting Honestly and Next Steps$j$, $j${"questions": [{"q": "Interpretar means to:", "options": ["Interpret spoken words", "Sing", "Translate a book", "Ask a question"]}, {"q": "For medical or legal matters, a volunteer should:", "options": ["Ask for a trained interpreter", "Refuse to help", "Use only slang", "Guess the words"]}, {"q": "Un momento, por favor, voy a buscar a un intérprete means:", "options": ["I interpreted yesterday", "Please wait a year", "I am an interpreter", "One moment, please, I am going to find an interpreter"]}, {"q": "Matthew 25:40 teaches that serving others is like:", "options": ["Winning a contest", "Earning a grade", "Avoiding work", "Serving Christ"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Serving Neighbors, Interpreting Honestly and Next Steps$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,3}'::int[], array[$j$Interpretar is for spoken language.$j$,$j$Accuracy protects the person being served.$j$,$j$It politely asks for a professional.$j$,$j$Jesus said whatever we do for the least of these, we do for Him.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Serving Neighbors, Interpreting Honestly and Next Steps$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Faith, Letters and Serving Others$j$, $j${"questions": [{"q": "Bienvenida is said to:", "options": ["Nobody", "A group of men", "One woman", "One man"]}, {"q": "Te damos gracias means:", "options": ["They thank me", "Thank them", "I give you thanks", "We give you thanks"]}, {"q": "Estimado señor is used in a:", "options": ["Text to a friend", "Casual note", "Formal letter", "Birthday card to a sibling"]}, {"q": "Cordialmente is a:", "options": ["Command", "Formal closing", "Question", "Greeting"]}, {"q": "Resucitó is in the:", "options": ["Preterite", "Present", "Future", "Imperfect"]}, {"q": "Había un hombre is in the:", "options": ["Command", "Imperfect", "Future", "Preterite"]}, {"q": "To translate in writing, use:", "options": ["Estar", "Interpretar", "Viajar", "Traducir"]}, {"q": "A good practice for serving with Spanish is to:", "options": ["Be honest about your level", "Pretend to know everything", "Avoid greeting people", "Use only English"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Faith, Letters and Serving Others$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,1,0,1,3,0}'::int[], array[$j$The ending a shows a woman.$j$,$j$Damos is the nosotros form of dar.$j$,$j$Estimado is formal.$j$,$j$It is a formal closing similar to cordially.$j$,$j$It tells a completed action.$j$,$j$Había describes the scene.$j$,$j$Traducir is for written language.$j$,$j$Honesty protects the people you serve.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Faith, Letters and Serving Others$j$ on conflict (item_id) do nothing;
end
$seed$;
